import type { AdditionalGlossaryTerm } from './glossary-additions';

export const criticalGlossaryAdditions: AdditionalGlossaryTerm[] = [
  { term: 'Inherent risk', category: 'Risk', domainSlug: 'risk-resilience', meaning: 'Exposure before considering the effect of controls that currently manage the scenario.', example: 'An internet payment service has high inherent fraud and availability exposure because of value, reachability and transaction volume.', where: 'At the start of a risk assessment, before current-control effectiveness is applied.', boundary: 'Inherent risk is not a fictional world with no management at all. The assessment method must state which baseline conditions are assumed.', related: ['Residual risk', 'Target risk', 'Risk treatment'] },
  { term: 'Current risk', category: 'Risk', domainSlug: 'risk-resilience', meaning: 'The exposure at the assessment date after considering controls as they actually operate, including known weaknesses and exceptions.', example: 'Current account-takeover risk reflects deployed multi-factor authentication, recovery gaps and observed attack activity.', where: 'Between inherent and target exposure in a maintained risk profile.', boundary: 'Current risk should not assume a control is effective merely because it is documented.', related: ['Inherent risk', 'Residual risk', 'Operating effectiveness'] },
  { term: 'Target risk', category: 'Risk', domainSlug: 'risk-resilience', meaning: 'The intended future exposure after approved treatments are implemented and shown to work.', example: 'A program targets lower outage risk after removing a single dependency and proving failover.', where: 'In treatment plans, target-state designs and investment decisions.', boundary: 'A target rating is an aspiration until evidence shows the planned changes work.', related: ['Residual risk', 'Risk treatment', 'Risk appetite'] },
  { term: 'Risk management', category: 'Risk', domainSlug: 'risk-resilience', meaning: 'Coordinated activities for directing and controlling how an organization handles uncertainty that can affect objectives.', example: 'A product decision identifies scenarios, analyzes exposure, chooses treatments, assigns owners and monitors change.', where: 'Inside strategy, investment, operations, projects, supplier management and day-to-day decisions.', boundary: 'A risk register is one record within risk management, not the complete discipline.', related: ['Risk appetite', 'Risk owner', 'Risk treatment'] },
  { term: 'Risk capacity', category: 'Risk', domainSlug: 'risk-resilience', meaning: 'The maximum level of exposure an organization can absorb without threatening viability, legal ability or a critical objective.', example: 'A liquidity threshold can constrain how much financial loss a firm can survive.', where: 'Above risk appetite as a hard or near-hard boundary for strategy and escalation.', boundary: 'Capacity is not the amount leaders prefer to take. Preference is expressed through appetite.', related: ['Risk appetite', 'Risk tolerance', 'Impact tolerance'] },
  { term: 'Risk tolerance', category: 'Risk', domainSlug: 'risk-resilience', meaning: 'A more specific acceptable variation around an objective, limit or performance target.', example: 'A service may tolerate a narrow range of failed transactions before escalation.', where: 'In measurable limits, operational thresholds and escalation rules.', related: ['Risk appetite', 'Risk capacity', 'Key risk indicator'] },
  { term: 'Impact tolerance', category: 'Resilience', domainSlug: 'risk-resilience', meaning: 'The maximum tolerable level of disruption to an important service, expressed through consequences and often time or volume.', example: 'A hospital defines how long a medication-ordering service can be disrupted before patient harm becomes unacceptable.', where: 'In operational resilience, business continuity and service recovery decisions.', boundary: 'Impact tolerance describes the unacceptable consequence boundary, while an RTO is a recovery target used to stay within it.', related: ['RTO', 'Operational resilience', 'Business continuity'] },
  { term: 'Risk owner', category: 'Risk', domainSlug: 'risk-resilience', meaning: 'The person accountable for understanding a defined risk, choosing or sponsoring treatment and accepting or escalating residual exposure within authority.', example: 'A payments executive owns the fraud scenario while technology and operations teams own supporting controls.', where: 'At the objective and decision level, often above individual control owners.', boundary: 'A risk owner does not personally operate every control and cannot accept exposure beyond delegated authority.', related: ['Control owner', 'Issue owner', 'Risk acceptance'] },
  { term: 'Issue owner', category: 'Governance', domainSlug: 'governance-assurance', meaning: 'The person accountable for correcting a defined deficiency or condition by an agreed date and proving closure.', example: 'A platform director owns remediation of unsupported privileged accounts.', where: 'In audit findings, risk exceptions, incidents and remediation programs.', related: ['Audit finding', 'Root cause analysis', 'Control owner'] },
  { term: 'Scenario analysis', category: 'Risk', domainSlug: 'risk-resilience', meaning: 'Structured exploration of a plausible cause, event and consequence under stated assumptions.', example: 'A team examines failure of a shared identity provider during a peak payment period.', where: 'In risk assessment, resilience planning, strategy and emerging-risk work.', boundary: 'A scenario is not a forecast. It tests decisions under plausible conditions.', related: ['Stress testing', 'Risk management', 'Concentration risk'] },
  { term: 'Stress testing', category: 'Risk', domainSlug: 'risk-resilience', meaning: 'Testing how a system, service, portfolio or plan behaves under severe but plausible conditions.', example: 'A bank tests liquidity and operational dependencies under simultaneous market and supplier disruption.', where: 'In finance, resilience, capacity, recovery and model-risk programs.', boundary: 'A passed test supports confidence only for the assumptions, severity and scope tested.', related: ['Scenario analysis', 'Impact tolerance', 'Resilience testing'] },
  { term: 'Concentration risk', category: 'Risk', domainSlug: 'risk-resilience', meaning: 'Exposure created when multiple important outcomes depend on the same supplier, region, platform, skill or other shared point of failure.', example: 'Two apparently independent vendors both rely on the same cloud region.', where: 'Across suppliers, technology platforms, portfolios, locations and people.', related: ['Third-party risk', 'Systemic risk', 'Single point of failure'] },
  { term: 'Risk acceptance', category: 'Risk', domainSlug: 'risk-resilience', meaning: 'An authorized decision to retain defined residual exposure for a stated period and rationale.', example: 'An executive accepts a low-impact legacy exception until a funded replacement date.', where: 'After assessment and treatment analysis, with an owner, authority, expiry and review trigger.', boundary: 'Acceptance is not inaction or silence. It must identify what is accepted and by whom.', related: ['Residual risk', 'Risk owner', 'Risk treatment'] },
  { term: 'Risk treatment', category: 'Risk', domainSlug: 'risk-resilience', meaning: 'A chosen response that changes, retains, shares, avoids, pursues or investigates exposure.', example: 'A service reduces outage risk through redundancy, shares financial consequences through insurance and accepts the remaining exposure.', where: 'Between risk analysis and monitored residual-risk decision.', related: ['Risk acceptance', 'Compensating control', 'Residual risk'] },
  { term: 'Risk velocity', category: 'Risk', domainSlug: 'risk-resilience', meaning: 'How quickly a risk event can develop into material consequences, affecting detection and response time.', example: 'Automated credential abuse can create large loss before a monthly review occurs.', where: 'In scenario analysis, monitoring cadence and escalation design.', related: ['Key risk indicator', 'Impact tolerance', 'Incident response'] },

  { term: 'Internal audit', category: 'Assurance', domainSlug: 'governance-assurance', meaning: 'An independent and objective assurance and advisory function designed to improve governance, risk management and control.', example: 'Internal audit assesses whether privileged-access governance is designed and operating effectively, reports findings and follows remediation.', where: 'The third line, functionally accountable to the board or audit committee and administratively supported by management.', boundary: 'Internal audit evaluates and advises; it should not own the controls or management decisions it later assures.', related: ['Audit charter', 'Audit universe', 'Third line'] },
  { term: 'Audit charter', category: 'Assurance', domainSlug: 'governance-assurance', meaning: 'A board-approved document defining internal audit purpose, authority, organizational position, access and responsibility.', example: 'The charter gives unrestricted access to relevant records and direct communication with the audit committee.', where: 'At the foundation of the internal-audit mandate and independence model.', related: ['Internal audit', 'Chief audit executive', 'Audit committee'] },
  { term: 'Audit universe', category: 'Assurance', domainSlug: 'governance-assurance', meaning: 'The maintained set of auditable entities, processes, systems, programs and themes from which assurance coverage is planned.', example: 'Cloud governance, payments, identity, suppliers and regulatory reporting appear as auditable units.', where: 'Between enterprise understanding and risk-based audit planning.', boundary: 'It is not a static organization chart. It must reflect services, change and shared dependencies.', related: ['Risk-based audit plan', 'Internal audit', 'Assurance map'] },
  { term: 'Risk-based audit plan', category: 'Assurance', domainSlug: 'governance-assurance', meaning: 'A prioritized plan of assurance and advisory work based on objectives, risk, change, stakeholder expectations and available capacity.', example: 'The plan increases identity and supplier coverage after major platform consolidation.', where: 'Approved and overseen by the board or audit committee, then updated as risk changes.', boundary: 'A plan should remain responsive; annual approval does not make emerging risk wait a year.', related: ['Audit universe', 'Internal audit', 'Risk assessment'] },
  { term: 'Audit finding', category: 'Assurance', domainSlug: 'governance-assurance', meaning: 'A supported conclusion that explains a condition, expected criterion, cause, consequence and agreed response.', example: 'Dormant privileged accounts remain active because the termination feed omits contractors, increasing unauthorized-access exposure.', where: 'In engagement reporting, remediation tracking and escalation.', boundary: 'A finding should not be only a control label or unsupported opinion.', related: ['Issue owner', 'Root cause analysis', 'Remediation'] },
  { term: 'Design effectiveness', category: 'Assurance', domainSlug: 'governance-assurance', meaning: 'Whether a control, if performed as designed by competent people, can reasonably achieve its objective.', example: 'A quarterly review that excludes machine identities is not suitably designed for complete privileged-access coverage.', where: 'Before or alongside testing operating effectiveness.', related: ['Operating effectiveness', 'Control objective', 'Control testing'] },
  { term: 'Attestation', category: 'Assurance', domainSlug: 'governance-assurance', meaning: 'An independent practitioner engagement that reports a conclusion about subject matter measured against suitable criteria.', example: 'A service auditor issues a SOC 2 report on a defined system and period.', where: 'In formal assurance engagements with defined responsibility, criteria, evidence and report users.', boundary: 'Attestation is not the same as self-declaration, certification or a general consulting review.', related: ['SOC 2', 'Audit', 'Certification'] },
  { term: 'First line', category: 'Governance', domainSlug: 'governance-assurance', meaning: 'Management and operational roles that own outcomes, make decisions and manage risk through daily work and controls.', example: 'An application team owns secure operation and remediation of its service.', where: 'Closest to products, services, customers and operations.', related: ['Second line', 'Third line', 'Three Lines Model'] },
  { term: 'Second line', category: 'Governance', domainSlug: 'governance-assurance', meaning: 'Specialist roles that provide expertise, frameworks, support, monitoring and challenge for risk-related matters.', example: 'A privacy or enterprise-risk function sets methods and challenges first-line assessments.', where: 'Between management ownership and independent assurance, with scope defined by governance.', boundary: 'The second line supports and challenges management but does not replace first-line ownership.', related: ['First line', 'Third line', 'Risk management'] },
  { term: 'Third line', category: 'Governance', domainSlug: 'governance-assurance', meaning: 'Internal audit, providing independent and objective assurance and advice on governance, risk management and control.', example: 'Internal audit reports assurance on the identity program directly to the audit committee.', where: 'Independent from the activities it assesses, with functional accountability to the board.', related: ['Internal audit', 'First line', 'Second line'] },
  { term: 'RACI', expansion: 'Responsible, Accountable, Consulted and Informed', category: 'Governance', domainSlug: 'governance-assurance', meaning: 'A role-mapping tool that distinguishes who performs work, who owns the result, who contributes and who receives updates.', example: 'The service owner is accountable, the platform team responsible, security consulted and support informed for a change.', where: 'In process, project, control and decision design.', boundary: 'A RACI does not define authority, competence or escalation by itself, and only one accountable owner is usually clearer.', related: ['Accountability', 'Control owner', 'Risk owner'] },
  { term: 'ICFR', expansion: 'Internal Control over Financial Reporting', category: 'Financial reporting', domainSlug: 'governance-assurance', meaning: 'Processes and controls that provide reasonable assurance about reliable external financial reporting and preparation of financial statements.', example: 'Access, change, interface and reconciliation controls support the integrity of a financial close.', where: 'Across entity-level controls, business processes, information technology general controls and application controls.', boundary: 'ICFR focuses on financial reporting. It does not represent every operational, compliance or cybersecurity objective.', related: ['SOX', 'ITGC', 'Application control'] },

  { term: 'Directive control', category: 'Control', domainSlug: 'governance-assurance', meaning: 'A control that establishes or communicates required behavior before work occurs.', example: 'A secure-development standard requires code review and approved dependencies.', where: 'Policies, standards, procedures, role instructions and training.', boundary: 'A directive states expectation; other controls and evidence show whether the behavior occurred.', related: ['Preventive control', 'Policy', 'Standard'] },
  { term: 'Deterrent control', category: 'Control', domainSlug: 'governance-assurance', meaning: 'A control intended to discourage unwanted behavior by increasing perceived likelihood or consequence of discovery.', example: 'A monitored-access warning and visible sanctions discourage casual misuse.', where: 'Before or during behavior, often alongside preventive and detective controls.', boundary: 'Deterrence depends on perception and culture and should not be the only safeguard for material risk.', related: ['Preventive control', 'Detective control', 'Security awareness'] },
  { term: 'Recovery control', category: 'Control', domainSlug: 'governance-assurance', meaning: 'A control that restores an acceptable service, data state or operating capability after disruption.', example: 'A tested restore rebuilds a clean service and verifies transaction integrity.', where: 'In continuity, disaster recovery, incident response and operational resilience.', boundary: 'A backup is only part of recovery; restoration time, dependency readiness and integrity must be tested.', related: ['Corrective control', 'RTO', 'RPO'] },
  { term: 'Administrative control', category: 'Control', domainSlug: 'governance-assurance', meaning: 'A safeguard implemented mainly through governance, people, policy or process.', example: 'Background screening and segregation of duties reduce insider-risk exposure.', where: 'Across organization, process and workforce practices.', boundary: 'Administrative, technical and physical describe implementation form, while preventive or detective describe purpose.', related: ['Technical control', 'Physical control', 'Directive control'] },
  { term: 'Technical control', category: 'Control', domainSlug: 'governance-assurance', meaning: 'A safeguard implemented through hardware, software or configured technology.', example: 'A firewall enforces an approved network path and records denied traffic.', where: 'Endpoints, networks, applications, identity, cloud and data platforms.', related: ['Administrative control', 'Physical control', 'Automated control'] },
  { term: 'Physical control', category: 'Control', domainSlug: 'governance-assurance', meaning: 'A safeguard implemented through the physical environment or access to people, equipment and facilities.', example: 'A badge-controlled door and visitor escort protect a server room.', where: 'Facilities, equipment, storage, work areas and environmental systems.', related: ['Administrative control', 'Technical control', 'Preventive control'] },
  { term: 'Manual control', category: 'Control', domainSlug: 'governance-assurance', meaning: 'A control whose performance and judgment depend primarily on a person.', example: 'A manager reviews and approves an exception report.', where: 'Business processes, governance, reconciliations and exception handling.', boundary: 'Manual controls can apply judgment but are vulnerable to inconsistency, fatigue and missing evidence.', related: ['Automated control', 'Hybrid control', 'Operating effectiveness'] },
  { term: 'Automated control', category: 'Control', domainSlug: 'governance-assurance', meaning: 'A control performed by configured technology without a person executing each instance.', example: 'A deployment pipeline rejects an unsigned release artifact.', where: 'Applications, platforms, workflows and infrastructure.', boundary: 'Reliability depends on logic, configuration, access, change controls, inputs and exception handling.', related: ['Manual control', 'Application control', 'ITGC'] },
  { term: 'Hybrid control', category: 'Control', domainSlug: 'governance-assurance', meaning: 'A control combining automated processing with human review or decision.', example: 'A system generates access anomalies and an owner investigates and certifies the result.', where: 'Where technology narrows a population but judgment remains necessary.', related: ['Manual control', 'Automated control', 'Evidence'] },
  { term: 'Entity-level control', category: 'Control', domainSlug: 'governance-assurance', meaning: 'A control operating broadly across an organization or major entity rather than one transaction.', example: 'Board oversight, ethics governance and the enterprise risk process influence many lower-level controls.', where: 'At governance, leadership, monitoring and organization-wide process levels.', related: ['Application control', 'ITGC', 'Control environment'] },
  { term: 'ITGC', expansion: 'Information Technology General Control', category: 'Control', domainSlug: 'governance-assurance', meaning: 'A broad technology control supporting reliable operation of systems and automated application controls, commonly across access, change and computer operations.', example: 'Approved production changes and controlled administrator access support the reliability of financial applications.', where: 'Across shared technology processes and platforms supporting in-scope applications.', boundary: 'An ITGC is not automatically effective for every application; scope, dependencies and evidence must be defined.', related: ['ICFR', 'Application control', 'SOX'] },
  { term: 'Application control', category: 'Control', domainSlug: 'governance-assurance', meaning: 'A control embedded in or closely tied to a business application and its transactions, data or workflow.', example: 'A three-way match prevents payment when purchase order, receipt and invoice disagree.', where: 'Within application configuration, validation, calculation, interface and workflow logic.', related: ['ITGC', 'Automated control', 'ICFR'] },

  { term: 'CPU', expansion: 'Central Processing Unit', category: 'Computing', domainSlug: 'computing-linux', meaning: 'The processor that executes machine instructions and coordinates computation.', example: 'The operating system schedules processes onto available CPU cores.', where: 'Inside endpoints, servers, mobile devices, embedded systems and cloud hosts.', related: ['RAM', 'Operating system', 'Process'] },
  { term: 'RAM', expansion: 'Random Access Memory', category: 'Computing', domainSlug: 'computing-linux', meaning: 'Fast working memory used by running programs and the operating system.', example: 'A database keeps frequently used pages in RAM to avoid slower storage access.', where: 'Between processor execution and persistent storage.', boundary: 'Ordinary RAM is volatile and normally loses contents when power is removed.', related: ['CPU', 'Virtual memory', 'Storage'] },
  { term: 'Operating system', expansion: 'OS', category: 'Computing', domainSlug: 'computing-linux', meaning: 'System software that manages hardware, processes, memory, files, devices, users and application interfaces.', example: 'Linux isolates processes and mediates access to files and network sockets.', where: 'Between applications and hardware or virtualized resources.', related: ['Kernel', 'Process', 'Filesystem hierarchy'] },
  { term: 'TCP/IP', expansion: 'Transmission Control Protocol and Internet Protocol', category: 'Networking', domainSlug: 'networks-internet', meaning: 'The practical protocol suite that underpins internet and most enterprise network communication.', example: 'IP routes packets while TCP can provide an ordered, reliable byte stream between endpoints.', where: 'Across link, internet, transport and application communication layers.', boundary: 'TCP/IP is a protocol suite and model, not one protocol and not identical to the seven-layer OSI reference model.', related: ['OSI model', 'IP', 'TCP'] },
  { term: 'OSI model', expansion: 'Open Systems Interconnection model', category: 'Networking', domainSlug: 'networks-internet', meaning: 'A seven-layer reference model for reasoning about how communication functions are separated and related.', example: 'A troubleshooter distinguishes an Ethernet link issue from an IP routing issue and a TLS session issue.', where: 'As a conceptual model spanning physical through application communication.', boundary: 'Real protocols and products do not always fit one layer cleanly. The model supports reasoning rather than prescribing an exact implementation.', related: ['TCP/IP', 'Packet', 'Frame'] },
  { term: 'PDU', expansion: 'Protocol Data Unit', category: 'Networking', domainSlug: 'networks-internet', meaning: 'The unit of information associated with a protocol layer, such as a frame, packet, segment or application message.', example: 'An IP packet is carried inside a link-layer frame across one network hop.', where: 'At each protocol layer as headers and payloads are added or interpreted.', related: ['Frame', 'Packet', 'Encapsulation'] },

  { term: 'IaaS', expansion: 'Infrastructure as a Service', category: 'Cloud', domainSlug: 'cloud-platforms', meaning: 'A cloud model providing virtualized compute, storage and networking while the customer manages operating systems, workloads, identities and much configuration.', example: 'A team deploys virtual machines and configures patching, firewalls and backups.', where: 'Closest to traditional infrastructure within the cloud service-model spectrum.', related: ['PaaS', 'SaaS', 'Shared responsibility'] },
  { term: 'PaaS', expansion: 'Platform as a Service', category: 'Cloud', domainSlug: 'cloud-platforms', meaning: 'A cloud model providing a managed application platform or runtime while the customer manages code, data, identity and service configuration.', example: 'Developers deploy an application without maintaining the underlying operating system.', where: 'Between raw infrastructure and complete software services.', related: ['IaaS', 'SaaS', 'Serverless'] },
  { term: 'SaaS', expansion: 'Software as a Service', category: 'Cloud', domainSlug: 'cloud-platforms', meaning: 'A complete provider-operated application consumed through a browser, application or API.', example: 'An organization configures a hosted collaboration platform and governs users, data and integrations.', where: 'At the application end of the cloud service-model spectrum.', boundary: 'Provider operation does not remove customer responsibility for identity, data use, configuration, monitoring and supplier risk.', related: ['IaaS', 'PaaS', 'Shared responsibility'] },

  { term: 'CI', expansion: 'Continuous Integration', category: 'Software delivery', domainSlug: 'software-delivery', meaning: 'The practice of integrating small code changes frequently and validating them through an automated build and test path.', example: 'Every pull request compiles, runs unit tests and checks dependencies before merge.', where: 'Between source control and releasable software artifacts.', related: ['Continuous delivery', 'Build pipeline', 'Source control'] },
  { term: 'Continuous delivery', expansion: 'CD', category: 'Software delivery', domainSlug: 'software-delivery', meaning: 'Keeping software in a releasable state through repeatable build, test and deployment automation, with production release still possibly requiring a decision.', example: 'A verified artifact can be promoted to production after an authorized business approval.', where: 'Across build, test, release and environment promotion.', boundary: 'Continuous delivery does not necessarily mean every change is automatically released to production.', related: ['CI', 'Continuous deployment', 'Release'] },
  { term: 'Continuous deployment', category: 'Software delivery', domainSlug: 'software-delivery', meaning: 'Automatically releasing every change that passes the defined production path without a separate manual release decision.', example: 'A low-risk service deploys a tested change automatically and monitors canary health.', where: 'At the final automated stage from releasable artifact to production.', boundary: 'It requires strong tests, observability, rollback and risk-based guardrails. It is not a universal maturity goal.', related: ['Continuous delivery', 'CI', 'Canary deployment'] },

  { term: 'System and Organization Controls', expansion: 'SOC', category: 'Assurance', domainSlug: 'governance-assurance', meaning: 'The AICPA family of service-organization reporting engagements, including SOC 1 and SOC 2.', example: 'A customer reviews a service provider report, scope, period, exceptions and complementary user entity controls.', where: 'In supplier assurance and service-auditor reporting.', boundary: 'This SOC is not a Security Operations Center and a SOC report is not a general certification.', aliases: ['SOC reports'], related: ['SOC 1', 'SOC 2', 'Attestation'] },
  { term: 'SOC 1', expansion: 'System and Organization Controls 1', category: 'Assurance', domainSlug: 'governance-assurance', meaning: 'A service-auditor report on controls at a service organization relevant to user entities’ internal control over financial reporting.', example: 'A payroll provider’s SOC 1 report supports customer and external-auditor understanding of financially relevant controls.', where: 'In financial-reporting and supplier-assurance work using a defined system and control objectives.', boundary: 'SOC 1 is not a broad cybersecurity report and is distinct from SOC 2 Trust Services Criteria.', related: ['System and Organization Controls', 'SOC 2', 'ICFR'] },
  { term: 'System on a Chip', expansion: 'SoC', category: 'Computing', domainSlug: 'computing-linux', meaning: 'An integrated circuit combining processor, memory controllers, interfaces and other system functions on one chip.', example: 'A mobile device SoC combines CPU, graphics, security and communication components.', where: 'Inside mobile, embedded, edge and personal computing devices.', boundary: 'SoC in hardware is unrelated to SOC reports or a Security Operations Center.', aliases: ['SoC hardware'], related: ['CPU', 'Firmware', 'Embedded system'] },
  { term: 'Separation of concerns', expansion: 'SoC', category: 'Software architecture', domainSlug: 'software-delivery', meaning: 'A design principle that divides a system into parts with distinct responsibilities so each can be understood and changed more safely.', example: 'Authentication logic is separated from presentation and payment calculation.', where: 'In software, system and organizational design.', boundary: 'This SoC is unrelated to System on a Chip, Security Operations Center and assurance reports.', related: ['Modularity', 'Software architecture', 'Least privilege'] },

  { term: 'Cyber kill chain', category: 'Security', domainSlug: 'security-operations-tools', meaning: 'A staged model for reasoning about how an intrusion progresses from preparation and delivery toward control and impact.', example: 'A defender maps phishing delivery, exploitation, installation, command and control, and actions on objectives to opportunities for interruption.', where: 'In threat modeling, defensive planning and incident analysis.', boundary: 'No single lifecycle represents every attack. MITRE ATT&CK provides a broader behavior knowledge base and attacks may skip, repeat or reorder stages.', related: ['MITRE ATT&CK', 'Attack path', 'Defense in depth'] },
  { term: 'Attack vector', category: 'Security', domainSlug: 'security-operations-tools', meaning: 'The route or method through which an attacker attempts to reach and affect a target.', example: 'A public login page, malicious attachment, supplier update or exposed remote service can be an attack vector.', where: 'Between an actor and an exposed asset or trust boundary.', boundary: 'A vector is a route, while a vulnerability is the weakness that may make the route successful.', related: ['Attack surface', 'Vulnerability', 'Exploit'] },
  { term: 'Exploit', category: 'Security', domainSlug: 'security-operations-tools', meaning: 'Code, input or a procedure that takes advantage of a vulnerability or unsafe condition to produce unintended behavior.', example: 'A crafted request causes an application to run an unauthorized command.', where: 'At the point where a reachable weakness is exercised.', boundary: 'A proof of concept may demonstrate a condition without being reliable, safe or weaponized for broad use.', related: ['Vulnerability', 'Zero-day', 'Attack vector'] },
  { term: 'Zero-day', category: 'Security', domainSlug: 'security-operations-tools', meaning: 'A vulnerability that is unknown to, or has no available fix from, the responsible vendor or maintainer when it is exploited or disclosed.', example: 'Attackers use a previously unknown browser flaw before a security update exists.', where: 'In vulnerability research, threat intelligence and emergency risk response.', boundary: 'Zero-day describes disclosure and patch timing, not automatic severity or proof of active exploitation.', related: ['Exploit', 'Vulnerability', 'Compensating control'] },
  { term: 'Initial access', category: 'Security operations', domainSlug: 'security-operations-tools', meaning: 'The adversary objective of obtaining an initial foothold in a target environment.', example: 'A stolen session, exposed service, malicious attachment or compromised supplier enables the first access.', where: 'Near the beginning of an intrusion, though access may be regained later.', related: ['MITRE ATT&CK', 'Persistence', 'Attack vector'] },
  { term: 'Persistence', category: 'Security operations', domainSlug: 'security-operations-tools', meaning: 'Methods used by an adversary to maintain access across restarts, credential changes or other interruptions.', example: 'A new cloud access key or scheduled task lets the attacker return after the original session is closed.', where: 'On endpoints, identities, applications, cloud control planes and network devices.', boundary: 'Persistence is the goal of retaining access, not every artifact that happens to remain on a system.', related: ['Initial access', 'Privilege escalation', 'Command and control'] },
  { term: 'Command and control', expansion: 'C2 or C&C', category: 'Security operations', domainSlug: 'security-operations-tools', meaning: 'Communication through which an adversary sends instructions to compromised systems and receives results.', example: 'Malware polls an external service for tasks and sends encrypted status messages.', where: 'Between compromised assets and adversary-controlled or abused infrastructure.', boundary: 'Unusual outbound traffic may be evidence of C2, but context and validation are required before containment.', related: ['Beaconing', 'Malware', 'Exfiltration'] },
  { term: 'Exfiltration', category: 'Security operations', domainSlug: 'security-operations-tools', meaning: 'Unauthorized transfer of data out of an environment or approved boundary.', example: 'A compromised account exports customer records to attacker-controlled cloud storage.', where: 'Across network, web, email, removable media, cloud and application channels.', boundary: 'Large transfer volume can be suspicious, but exfiltration is defined by unauthorized removal, not size alone.', related: ['DLP', 'Command and control', 'Data classification'] },
  { term: 'Virus', category: 'Malware', domainSlug: 'security-operations-tools', meaning: 'Malicious code that attaches to a host file or program and replicates when that host is executed or shared.', example: 'An infected executable modifies other executable files when a user runs it.', where: 'On endpoints, removable media and file-sharing paths.', boundary: 'Virus is not a synonym for all malware. A worm can spread without attaching to a host file.', related: ['Worm', 'Trojan', 'Malware'] },
  { term: 'Worm', category: 'Malware', domainSlug: 'security-operations-tools', meaning: 'Self-propagating malicious code that spreads between systems, commonly by abusing network reachability and vulnerabilities.', example: 'A worm scans for a vulnerable service and copies itself to reachable hosts.', where: 'Across networks and connected systems.', boundary: 'A worm’s defining property is autonomous propagation, not its payload or business impact.', related: ['Virus', 'Botnet', 'Network segmentation'] },
  { term: 'Trojan', expansion: 'Trojan horse', category: 'Malware', domainSlug: 'security-operations-tools', meaning: 'Malicious software presented as, or bundled with, something legitimate to persuade a user or process to run it.', example: 'A fake software update installs a remote-access payload.', where: 'In downloads, attachments, cracked software, mobile applications and supply-chain packages.', boundary: 'A Trojan describes deceptive delivery and does not necessarily self-replicate.', related: ['Social engineering', 'Malware', 'Remote access trojan'] },
  { term: 'Rootkit', category: 'Malware', domainSlug: 'security-operations-tools', meaning: 'Software or modification designed to maintain privileged access and conceal processes, files, drivers or system changes.', example: 'A kernel-level rootkit hides malicious activity from ordinary operating-system tools.', where: 'In operating-system, boot, firmware or user-space layers.', boundary: 'Rootkit refers to concealment and privileged persistence, not every privileged compromise.', related: ['Persistence', 'Kernel', 'Secure boot'] },
  { term: 'Spyware', category: 'Malware', domainSlug: 'security-operations-tools', meaning: 'Software that covertly monitors activity or collects information without appropriate knowledge or consent.', example: 'A malicious application captures browsing, messages and device information.', where: 'On endpoints, browsers and mobile devices.', related: ['Keylogger', 'Malware', 'Privacy'] },
  { term: 'Keylogger', category: 'Malware', domainSlug: 'security-operations-tools', meaning: 'Software or hardware that records keystrokes, often to capture credentials, messages or sensitive input.', example: 'Malware records a password before it is protected by an encrypted network session.', where: 'At the input, operating-system, browser or physical-device layer.', boundary: 'Transport encryption cannot protect input captured before it enters the encrypted session.', related: ['Spyware', 'Credential theft', 'Endpoint security'] },
  { term: 'Botnet', category: 'Security', domainSlug: 'security-operations-tools', meaning: 'A collection of compromised devices controlled together for tasks such as denial of service, spam, fraud, scanning or proxying.', example: 'Thousands of infected routers send coordinated traffic toward a service.', where: 'Across consumer, enterprise, server, cloud and Internet of Things devices.', related: ['Command and control', 'DDoS', 'Worm'] },
  { term: 'Watering hole attack', category: 'Social engineering', domainSlug: 'security-operations-tools', meaning: 'Compromising a site or service frequently used by a target group so visits become an opportunity for infection, credential theft or redirection.', example: 'An attacker modifies an industry portal used by employees of selected organizations.', where: 'At trusted community websites, software portals or online services.', boundary: 'Unlike broad phishing, the attacker places the lure where the target already goes.', related: ['Drive-by download', 'Supply-chain attack', 'Initial access'] },
  { term: 'Drive-by download', category: 'Security', domainSlug: 'security-operations-tools', meaning: 'A download or execution triggered through visiting a web page, sometimes without clear user intent, by abusing browser behavior or a vulnerability.', example: 'A compromised page redirects a vulnerable browser to exploit code.', where: 'Across browsers, extensions, advertising networks and web content.', related: ['Watering hole attack', 'Exploit kit', 'Browser security'] },
  { term: 'Vishing', expansion: 'Voice phishing', category: 'Social engineering', domainSlug: 'security-operations-tools', meaning: 'Social engineering conducted through voice calls or voice messages to obtain information or influence action.', example: 'A caller impersonates support and asks a user to approve a sign-in prompt.', where: 'Phone, conferencing and voice-message channels.', related: ['Phishing', 'Smishing', 'Pretexting'] },
  { term: 'Smishing', expansion: 'SMS phishing', category: 'Social engineering', domainSlug: 'security-operations-tools', meaning: 'Phishing delivered through text or mobile messaging to direct a person toward an unsafe link, call or action.', example: 'A message claiming to be from a bank links to a fake sign-in page.', where: 'SMS, rich communication services and mobile messaging applications.', related: ['Phishing', 'Vishing', 'QR phishing'] },
  { term: 'Pretexting', category: 'Social engineering', domainSlug: 'security-operations-tools', meaning: 'Using a fabricated identity or situation to create trust and persuade someone to disclose information or perform an action.', example: 'An attacker poses as a new employee who urgently needs an account reset.', where: 'Calls, email, chat, in-person interactions and support processes.', related: ['Vishing', 'Business email compromise', 'Identity proofing'] },
  { term: 'Baiting', category: 'Social engineering', domainSlug: 'security-operations-tools', meaning: 'Offering something attractive or useful to induce unsafe behavior.', example: 'A labeled USB drive is left where an employee may connect it to a workstation.', where: 'Physical media, downloads, promotions and online content.', related: ['Social engineering', 'Removable media', 'Trojan'] },
  { term: 'Tailgating', category: 'Physical security', domainSlug: 'security-operations-tools', meaning: 'Entering a controlled physical area by closely following an authorized person without completing the required access check.', example: 'A visitor carrying boxes follows an employee through a badge-controlled door.', where: 'Building entrances, secure floors and restricted rooms.', boundary: 'Piggybacking is sometimes used when the authorized person knowingly permits the entry; terminology varies.', related: ['Physical control', 'Security awareness', 'Visitor management'] },
  { term: 'Shoulder surfing', category: 'Physical security', domainSlug: 'security-operations-tools', meaning: 'Observing a screen, keyboard or document to obtain sensitive information.', example: 'A person watches a PIN entry in a crowded public area.', where: 'Offices, transport, public spaces, service counters and video surveillance.', related: ['Privacy screen', 'Physical control', 'Credential theft'] },
  { term: 'Non-repudiation', category: 'Cryptography', domainSlug: 'security-operations-tools', meaning: 'Assurance that a party cannot credibly deny a specific action or communication, supported by technical evidence and the surrounding legal and operational process.', example: 'A digital signature, trusted timestamp and protected signing key support a dispute about who approved a document.', where: 'In signed transactions, approvals, messages and evidence systems.', boundary: 'A digital signature contributes to non-repudiation but does not prove who controlled the key or whether the signer acted voluntarily.', related: ['Digital signature', 'Accountability', 'PKI'] },
  { term: 'Data at rest', category: 'Data security', domainSlug: 'data-analytics', meaning: 'Data stored on media rather than actively moving between systems.', example: 'Customer records stored in a database snapshot are data at rest.', where: 'Databases, files, backups, devices and object storage.', boundary: 'Storage encryption protects media and some access paths, but authorized applications may still expose decrypted data.', related: ['Data in transit', 'Data in use', 'Encryption'] },
  { term: 'Data in transit', category: 'Data security', domainSlug: 'data-analytics', meaning: 'Data moving between processes, devices, networks or trust domains.', example: 'An application request protected by Transport Layer Security carries data in transit.', where: 'Network connections, message queues, replication and application interfaces.', boundary: 'Encrypted transport does not validate every endpoint, user or business action by itself.', related: ['Data at rest', 'Data in use', 'TLS'] },
  { term: 'Data in use', category: 'Data security', domainSlug: 'data-analytics', meaning: 'Data being actively processed, viewed, transformed or held in working memory.', example: 'A payroll application decrypts a record in memory so an authorized calculation can run.', where: 'Applications, processors, memory, analytical tools and user interfaces.', boundary: 'Data must often be decrypted for use, so authorization, isolation, logging and output controls remain important.', related: ['Data at rest', 'Data in transit', 'Trusted execution environment'] },

  { term: 'Wordlist', category: 'Authentication', domainSlug: 'identity-access', meaning: 'A text file or structured collection containing candidate passwords to test in a defined order.', example: 'An authorized audit uses a protected list of known-compromised and organization-specific weak password patterns against synthetic or approved verifier data.', where: 'In password auditing, password blocklist design and research into human password choice.', boundary: 'A wordlist is candidate data, not authority to test an account. It may contain breach-derived or sensitive material that requires controlled handling.', aliases: ['Password dictionary', 'Dictionary file'], related: ['Dictionary attack', 'Password blocklist', 'Password cracking'] },
  { term: 'Dictionary attack', category: 'Authentication', domainSlug: 'identity-access', meaning: 'A password-guessing method that tries candidates from a wordlist instead of enumerating every possible character combination.', example: 'A test checks whether users selected common words, breach-derived passwords or predictable organization-specific phrases.', where: 'Offline against approved hashes or online against a live verifier under different safety controls.', boundary: 'Dictionary attacks may transform candidates with rules. They are not limited to words found in a language dictionary.', related: ['Wordlist', 'Brute-force attack', 'Password spraying'] },
  { term: 'Password cracking', category: 'Authentication', domainSlug: 'identity-access', meaning: 'Recovering or identifying a password by evaluating candidate secrets against a password hash, encrypted artifact or other verifier.', example: 'An approved audit evaluates candidates against a copied test hash to measure resistance to offline guessing.', where: 'In forensic recovery, password audits and adversary activity after verifier data is obtained.', boundary: 'Cracking usually describes offline evaluation. Repeatedly submitting passwords to a live service is online guessing and creates different operational risk.', related: ['Offline password cracking', 'Password hash', 'Password guessing'] },
  { term: 'Offline password cracking', category: 'Authentication', domainSlug: 'identity-access', meaning: 'Evaluating password candidates locally against copied password hashes or encrypted artifacts without contacting the original authentication service.', example: 'hashcat tests an approved set of test hashes on an isolated audit workstation.', where: 'After verifier material has been exported, recovered or stolen.', boundary: 'No live rate limit or lockout slows the attempt, so storage algorithm, salt, work factor and password unpredictability become central.', related: ['Password cracking', 'Salt', 'Password hashing'] },
  { term: 'Online password guessing', category: 'Authentication', domainSlug: 'identity-access', meaning: 'Submitting candidate credentials to a live authentication service and observing whether the service accepts or rejects them.', example: 'A tightly scoped test uses synthetic accounts to verify throttling and alert behavior.', where: 'At web, remote-access, directory, email and other network login interfaces.', boundary: 'It can lock accounts, trigger incidents or disrupt a service. Use written authority, attempt limits, monitoring and stop conditions.', related: ['Password spraying', 'Credential stuffing', 'Rate limiting'] },
  { term: 'Rainbow table', category: 'Authentication', domainSlug: 'identity-access', meaning: 'A precomputed time-memory trade-off structure used to look up candidate plaintexts for unsalted or predictably salted password hashes.', example: 'A legacy Windows hash is compared with a compatible precomputed table during a controlled demonstration.', where: 'In specialized offline password-hash research and legacy audits.', boundary: 'A unique random salt for every password removes the reusable precomputation advantage. Modern slow password hashing also changes the economics.', related: ['Salt', 'RainbowCrack', 'Password hash'] },
  { term: 'Brute-force attack', category: 'Authentication', domainSlug: 'identity-access', meaning: 'Systematically trying every candidate in a defined search space until one succeeds or the space is exhausted.', example: 'A test enumerates every four-digit PIN to show why retry limits are required.', where: 'Against offline verifiers or live authentication with very different practical limits.', boundary: 'Not every password attack is brute force. Wordlists, spraying and credential stuffing use more selective candidate strategies.', related: ['Dictionary attack', 'Password spraying', 'Rate limiting'] },
  { term: 'Password blocklist', category: 'Authentication', domainSlug: 'identity-access', meaning: 'A set of common, expected or known-compromised passwords that a verifier rejects when a password is established or changed.', example: 'A service rejects a password found in breach corpuses or derived from the service name and explains why the user must choose another.', where: 'At password enrollment and reset, before the verifier is stored.', boundary: 'A defensive blocklist is not the same as using a wordlist to guess passwords, and an excessively large blocklist adds little benefit to a rate-limited online verifier.', related: ['Wordlist', 'Password policy', 'Rate limiting'] },
  { term: 'Salt', category: 'Cryptography', domainSlug: 'identity-access', meaning: 'A unique non-secret value combined with a password when deriving its stored verifier so identical passwords do not produce identical hashes.', example: 'Two users choose the same password but receive different stored verifier values because their salts differ.', where: 'Stored alongside each password verifier as an input to the password-hashing scheme.', boundary: 'Salt prevents reusable precomputation and direct equality comparison. It does not make fast hashing safe or a predictable password strong.', related: ['Password hash', 'Password hashing', 'Rainbow table'] },
  { term: 'Password hash', category: 'Authentication', domainSlug: 'identity-access', meaning: 'A stored password verifier produced by a password-hashing scheme from the password, a salt and a cost factor.', example: 'The verifier recalculates the candidate using the stored algorithm parameters and compares the result without storing the plaintext password.', where: 'In an authentication system’s protected verifier database.', boundary: 'A fast general-purpose digest such as plain SHA-256 is not suitable password storage merely because it is a hash.', related: ['Password hashing', 'Salt', 'Offline password cracking'] },
  { term: 'Buffer overflow', category: 'Software security', domainSlug: 'software-delivery', meaning: 'Writing more data to a bounded memory region than it can hold, causing adjacent memory to be overwritten.', example: 'An image decoder allocates too little memory for declared dimensions and copies decoded pixels beyond the buffer.', where: 'In memory-unsafe code, native libraries, parsers, drivers, firmware and interfaces to them.', boundary: 'The result may be a crash, corruption, disclosure or altered control flow. Exploitability depends on location, protections and attacker control.', related: ['Stack overflow', 'Heap overflow', 'Memory safety'] },
  { term: 'Stack overflow', category: 'Software security', domainSlug: 'software-delivery', meaning: 'Exhausting or corrupting stack memory, often through unbounded recursion or an out-of-bounds write to a stack buffer.', example: 'A native function copies an oversized value into a fixed local array and overwrites nearby stack data.', where: 'In function call state and local variables held on a thread stack.', boundary: 'Stack exhaustion and stack-buffer overflow are related but distinct failure mechanisms.', related: ['Buffer overflow', 'Call stack', 'Memory safety'] },
  { term: 'Heap overflow', category: 'Software security', domainSlug: 'software-delivery', meaning: 'Writing beyond an allocated object or buffer in dynamically managed heap memory.', example: 'A parser copies a field beyond an allocated heap object and corrupts a neighboring object or allocator metadata.', where: 'In dynamically allocated application and library memory.', related: ['Buffer overflow', 'Use-after-free', 'Memory safety'] },
  { term: 'Memory safety', category: 'Software security', domainSlug: 'software-delivery', meaning: 'The property that a program accesses only valid memory objects, within their bounds and valid lifetimes, using permitted operations.', example: 'A memory-safe language prevents an ordinary array write from silently overwriting an unrelated object.', where: 'Across language semantics, compiler checks, runtimes, libraries and native interfaces.', boundary: 'Memory safety prevents a major weakness family but does not by itself provide correct authorization, business logic or secure design.', related: ['Bounds checking', 'Buffer overflow', 'Use-after-free'] },
  { term: 'Bounds checking', category: 'Software security', domainSlug: 'software-delivery', meaning: 'Verifying that an index, length, pointer range or calculated size remains within the valid boundary of an object before access.', example: 'An image parser checks width, height, multiplication overflow and final decoded size before allocation and copy.', where: 'At array, buffer, string, parser and memory-copy operations.', related: ['Buffer overflow', 'Memory safety', 'Integer overflow'] },
  { term: 'Input validation', category: 'Software security', domainSlug: 'software-delivery', meaning: 'Checking that incoming data satisfies expected syntax, type, length, range, structure and business rules before it is accepted.', example: 'An order service rejects a negative quantity, an unknown currency and a payload outside the documented schema.', where: 'At every trust boundary, including user interfaces, APIs, files, messages and supplier feeds.', boundary: 'Validation does not replace parameterized queries, contextual output encoding or authorization.', related: ['Injection', 'Allowlist', 'Output encoding'] },
  { term: 'Output encoding', category: 'Software security', domainSlug: 'software-delivery', meaning: 'Representing untrusted data so it is interpreted as data rather than executable syntax in a specific output context.', example: 'A template encodes user-controlled text for an HTML text node before rendering it.', where: 'At the final boundary before data enters HTML, JavaScript, a URL, CSS, a command or another interpreter context.', boundary: 'Encoding is context-specific. A value safely encoded for HTML text may be unsafe in JavaScript or a URL.', related: ['Cross-site scripting', 'Input validation', 'Injection'] },
  { term: 'Injection', category: 'Software security', domainSlug: 'software-delivery', meaning: 'A weakness in which untrusted data changes the structure or meaning of a command, query, expression or interpreter input.', example: 'String concatenation lets a supplied value alter a database query instead of remaining a parameter value.', where: 'At database, operating-system, template, directory, expression and other interpreter boundaries.', boundary: 'Input validation helps, but safe parameterization and context-aware interfaces prevent data from becoming syntax.', related: ['SQL injection', 'Command injection', 'Input validation'] },
  { term: 'Race condition', category: 'Software security', domainSlug: 'software-delivery', meaning: 'A defect in which correctness or security depends on operations occurring in a particular order or timing relationship that is not reliably enforced.', example: 'Two payment requests both read sufficient balance before either commits a deduction.', where: 'In concurrent programs, distributed systems, files, transactions, workflows and retries.', boundary: 'The fix is to preserve the business or security invariant under concurrency, not merely to add a delay.', related: ['TOCTOU', 'Atomic operation', 'Idempotency'] },
  { term: 'TOCTOU', expansion: 'Time of check to time of use', category: 'Software security', domainSlug: 'software-delivery', meaning: 'A race condition in which a program checks a resource or condition, another actor changes it, and the program later uses an assumption that is no longer true.', example: 'A program validates a file path, but the path is replaced before the privileged open operation.', where: 'At file, authorization, transaction and distributed-state boundaries.', related: ['Race condition', 'Atomic operation', 'Symlink attack'] },
  { term: 'Broken access control', category: 'Application security', domainSlug: 'software-delivery', meaning: 'Failure to enforce whether an authenticated subject may perform a requested action on a specific object in the current context.', example: 'Changing an invoice identifier returns another customer’s record because the server checks only that the requester is signed in.', where: 'At Application Programming Interface, application, data, tenant and workflow authorization boundaries.', boundary: 'Hiding an interface element or validating an identifier format is not server-side authorization.', related: ['Authorization', 'IDOR', 'Least privilege'] },
  { term: 'Insecure design', category: 'Software security', domainSlug: 'software-delivery', meaning: 'A security weakness caused by missing or ineffective design controls rather than a single implementation mistake.', example: 'A recovery workflow allows account takeover because it has no reliable identity proofing or abuse-resistant decision model.', where: 'In requirements, architecture, trust boundaries, workflows and business rules.', boundary: 'A perfectly implemented unsafe design remains unsafe. Threat modeling and secure design address the missing control before code-level testing.', related: ['Threat modeling', 'Secure by design', 'Business logic vulnerability'] },
  { term: 'Custom cryptography', category: 'Cryptography', domainSlug: 'software-delivery', meaning: 'A home-grown algorithm, protocol or construction intended to provide a security property such as encryption, hashing or signatures.', example: 'A developer obscures data with a reversible transform and calls it encryption.', where: 'In application code, proprietary protocols, embedded systems and integrations.', boundary: 'Do not create custom cryptography for production security. Use reviewed standards and maintained libraries with correct key management.', aliases: ['Roll your own crypto'], related: ['Cryptographic algorithm', 'Key management', 'Insecure design'] },
  { term: 'Physical access', category: 'Physical security', domainSlug: 'security-operations-tools', meaning: 'Direct possession of or proximity to a device, storage medium, facility, port or component.', example: 'A thief removes an unencrypted laptop drive and reads it from another system.', where: 'At device, room, rack, port, removable-media and supply-chain boundaries.', boundary: 'Physical access can bypass many operating-system controls, so encryption, secure boot, hardware-backed keys and physical safeguards are separate requirements.', related: ['Full-disk encryption', 'Secure boot', 'Physical control'] },
  { term: 'Full-disk encryption', expansion: 'FDE', category: 'Data security', domainSlug: 'computing-linux', meaning: 'Encryption that protects the contents of a storage volume when the device is powered off or the volume is not unlocked.', example: 'A stolen laptop drive cannot be read from another computer without the recovery key or authorized unlock process.', where: 'At endpoint, server and removable-storage media boundaries.', boundary: 'Full-disk encryption does not protect data after an authorized user or running system unlocks the volume. Identity, session, application and backup controls still matter.', related: ['Data at rest', 'Physical access', 'Secure boot'] },
];
